CREATE UNIQUE INDEX projects_id_owner ON projects(id,user_id);
CREATE TABLE task_recurrences(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,remote_updated_at TEXT,sync_state TEXT NOT NULL DEFAULT 'local' CHECK(sync_state IN ('local','imported','modified')),title TEXT NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 300),description TEXT NOT NULL,frequency TEXT NOT NULL CHECK(frequency IN ('daily','weekdays','weekly','monthly','yearly')),interval_days INTEGER NOT NULL CHECK(interval_days BETWEEN 1 AND 366),start_date TEXT NOT NULL,end_date TEXT,occurrence_limit INTEGER CHECK(occurrence_limit BETWEEN 1 AND 10000),weekdays TEXT NOT NULL,timezone TEXT NOT NULL CHECK(length(timezone) BETWEEN 1 AND 64),status TEXT NOT NULL CHECK(status IN ('active','paused','archived')),reminder_time TEXT,category TEXT NOT NULL,priority TEXT NOT NULL CHECK(priority IN ('low','medium','high')),project_id TEXT,FOREIGN KEY(project_id,user_id) REFERENCES projects(id,user_id) ON DELETE RESTRICT,UNIQUE(id,user_id));
CREATE TABLE task_occurrences(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,remote_updated_at TEXT,sync_state TEXT NOT NULL DEFAULT 'local' CHECK(sync_state IN ('local','imported','modified')),recurrence_id TEXT NOT NULL,local_date TEXT NOT NULL,task_id TEXT NOT NULL,UNIQUE(recurrence_id,local_date),FOREIGN KEY(task_id,user_id) REFERENCES tasks(id,user_id) ON DELETE RESTRICT,FOREIGN KEY(recurrence_id,user_id) REFERENCES task_recurrences(id,user_id) ON DELETE RESTRICT);
CREATE INDEX task_recurrences_updated ON task_recurrences(updated_at,id);
CREATE INDEX task_occurrence_parent ON task_occurrences(recurrence_id,local_date);
CREATE TRIGGER sync_task_recurrences_insert AFTER INSERT ON task_recurrences WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,payload,base_revision,base_updated_at) VALUES('task_recurrences',NEW.id,'put',json_object('id',NEW.id,'user_id',NEW.user_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'title',NEW.title,'description',NEW.description,'frequency',NEW.frequency,'interval_days',NEW.interval_days,'start_date',NEW.start_date,'end_date',NEW.end_date,'occurrence_limit',NEW.occurrence_limit,'weekdays',NEW.weekdays,'timezone',NEW.timezone,'status',NEW.status,'reminder_time',NEW.reminder_time,'category',NEW.category,'priority',NEW.priority,'project_id',NEW.project_id),(SELECT revision FROM native_sync_meta WHERE entity_table='task_recurrences' AND id=NEW.id),COALESCE((SELECT remote_updated_at FROM native_sync_meta WHERE entity_table='task_recurrences' AND id=NEW.id),NEW.remote_updated_at)); END;
CREATE TRIGGER sync_task_recurrences_update AFTER UPDATE ON task_recurrences WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,payload,base_revision,base_updated_at) VALUES('task_recurrences',NEW.id,'put',json_object('id',NEW.id,'user_id',NEW.user_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'title',NEW.title,'description',NEW.description,'frequency',NEW.frequency,'interval_days',NEW.interval_days,'start_date',NEW.start_date,'end_date',NEW.end_date,'occurrence_limit',NEW.occurrence_limit,'weekdays',NEW.weekdays,'timezone',NEW.timezone,'status',NEW.status,'reminder_time',NEW.reminder_time,'category',NEW.category,'priority',NEW.priority,'project_id',NEW.project_id),(SELECT revision FROM native_sync_meta WHERE entity_table='task_recurrences' AND id=NEW.id),COALESCE((SELECT remote_updated_at FROM native_sync_meta WHERE entity_table='task_recurrences' AND id=NEW.id),NEW.remote_updated_at)); END;
CREATE TRIGGER sync_task_recurrences_delete AFTER DELETE ON task_recurrences WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,base_revision,base_updated_at) VALUES('task_recurrences',OLD.id,'delete',(SELECT revision FROM native_sync_meta WHERE entity_table='task_recurrences' AND id=OLD.id),OLD.remote_updated_at); END;
CREATE TRIGGER sync_task_occurrences_insert AFTER INSERT ON task_occurrences WHEN (SELECT applying FROM native_sync_control)=0 BEGIN INSERT INTO native_sync_outbox(entity_table,id,action,payload,base_revision,base_updated_at) VALUES('task_occurrences',NEW.id,'put',json_object('id',NEW.id,'user_id',NEW.user_id,'created_at',NEW.created_at,'updated_at',NEW.updated_at,'recurrence_id',NEW.recurrence_id,'local_date',NEW.local_date,'task_id',NEW.task_id),(SELECT revision FROM native_sync_meta WHERE entity_table='task_occurrences' AND id=NEW.id),COALESCE((SELECT remote_updated_at FROM native_sync_meta WHERE entity_table='task_occurrences' AND id=NEW.id),NEW.remote_updated_at)); END;
